package cat.narezany.margyt;

import android.graphics.Bitmap;
import android.graphics.BitmapFactory;
import android.util.Base64;

/**
 * The bottom bar's icons, SF Symbols drawn as white shapes on nothing, to be
 * tinted when they are drawn. Eight of them: home, friends, inbox and profile,
 * each outlined and filled. Decoded once, when first wanted.
 */
final class SfIcons {
    private SfIcons() {}

    /** Slot = 2 * tab + (filled ? 1 : 0), the tabs being home, friends, inbox, profile. */
    private static final String[] DATA = {
        // house 86x77
        "",
        // house.fill 86x77
        "",
        // person.2 96x64
        "",
        // person.2.fill 96x63
        "",
        // message 92x77
        "",
        // message.fill 92x77
        "",
        // person 73x77
        "",
        // person.fill 72x77
        "",
    };

    private static final Bitmap[] DONE = new Bitmap[DATA.length];

    static Bitmap get(int tab, boolean filled) {
        int slot = tab * 2 + (filled ? 1 : 0);
        if (slot < 0 || slot >= DATA.length) return null;
        Bitmap have = DONE[slot];
        if (have == null) {
            byte[] bytes = Base64.decode(DATA[slot], Base64.DEFAULT);
            have = BitmapFactory.decodeByteArray(bytes, 0, bytes.length);
            DONE[slot] = have;
        }
        return have;
    }
}
